local LMG2L = {};

-- Services
local Players = game:GetService("Players")
local Lighting = game:GetService("Lighting")
local Workspace = game:GetService("Workspace")

local LocalPlayer = Players.LocalPlayer
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

-- Players.darkness39229495394.PlayerGui.ScreenGui
LMG2L["ScreenGui_1"] = Instance.new("ScreenGui", PlayerGui);
LMG2L["ScreenGui_1"]["ZIndexBehavior"] = Enum.ZIndexBehavior.Sibling;

-- Players.darkness39229495394.PlayerGui.ScreenGui.Frame
LMG2L["Frame_2"] = Instance.new("Frame", LMG2L["ScreenGui_1"]);
LMG2L["Frame_2"]["BorderSizePixel"] = 3;
LMG2L["Frame_2"]["BackgroundColor3"] = Color3.fromRGB(0, 0, 0);
LMG2L["Frame_2"]["Size"] = UDim2.new(0, 254, 0, 136);
LMG2L["Frame_2"]["Position"] = UDim2.new(0, 302, 0, 92);
LMG2L["Frame_2"]["BorderColor3"] = Color3.fromRGB(186, 74, 255);

-- Players.darkness39229495394.PlayerGui.ScreenGui.Frame.TextLabel
LMG2L["TextLabel_3"] = Instance.new("TextLabel", LMG2L["Frame_2"]);
LMG2L["TextLabel_3"]["BorderSizePixel"] = 0;
LMG2L["TextLabel_3"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextLabel_3"]["TextColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextLabel_3"]["BackgroundTransparency"] = 0.9;
LMG2L["TextLabel_3"]["Size"] = UDim2.new(0, 254, 0, 40);
LMG2L["TextLabel_3"]["Text"] = [[k0van gui v12]];
