-- Players.darkness39229495394.PlayerGui.ScreenGui.Frame.TextLabel.ImageLabel
LMG2L["ImageLabel_4"] = Instance.new("ImageLabel", LMG2L["TextLabel_3"]);
LMG2L["ImageLabel_4"]["BorderSizePixel"] = 0;
LMG2L["ImageLabel_4"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["ImageLabel_4"]["Image"] = [[rbxassetid://115622440355549]];
LMG2L["ImageLabel_4"]["Size"] = UDim2.new(0, 178, 0, 64);
LMG2L["ImageLabel_4"]["BackgroundTransparency"] = 0.9;
LMG2L["ImageLabel_4"]["Rotation"] = 9;
LMG2L["ImageLabel_4"]["Position"] = UDim2.new(0, 146, 0, -36);

-- Trackers for Toggles
local skyboxToggled = false
local originalSkybox = {}
local decalSpamToggled = false
local spawnedDecals = {}
local currentSound = nil
local discoToggled = false
local originalAmbient = Lighting.Ambient
local originalOutdoor = Lighting.OutdoorAmbient

-- Skybox Button
LMG2L["TextButton_5"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_5"]["BorderSizePixel"] = 0;
LMG2L["TextButton_5"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_5"]["Size"] = UDim2.new(0, 50, 0, 26);
LMG2L["TextButton_5"]["Text"] = [[skybox]];
LMG2L["TextButton_5"]["Position"] = UDim2.new(0, 12, 0, 42);

LMG2L["TextButton_5"].MouseButton1Click:Connect(function()
	skyboxToggled = not skyboxToggled
	local sky = Lighting:FindFirstChildOfClass("Sky")

	if skyboxToggled then
		if sky then
			originalSkybox = {sky.SkyboxBk, sky.SkyboxDn, sky.SkyboxFt, sky.SkyboxLf, sky.SkyboxRt, sky.SkyboxUp}
		else
			sky = Instance.new("Sky", Lighting)
		end
		local id = "rbxassetid://115622440355549"
		sky.SkyboxBk, sky.SkyboxDn, sky.SkyboxFt, sky.SkyboxLf, sky.SkyboxRt, sky.SkyboxUp = id, id, id, id, id, id
		LMG2L["TextButton_5"].TextColor3 = Color3.fromRGB(0, 200, 0)
	else
		if sky and #originalSkybox > 0 then
			sky.SkyboxBk, sky.SkyboxDn, sky.SkyboxFt, sky.SkyboxLf, sky.SkyboxRt, sky.SkyboxUp = unpack(originalSkybox)
		elseif sky then
			sky:Destroy()
		end
		LMG2L["TextButton_5"].TextColor3 = Color3.fromRGB(0, 0, 0)
	end
end)

-- Decal Spam Button
LMG2L["TextButton_6"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_6"]["BorderSizePixel"] = 0;
LMG2L["TextButton_6"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_6"]["Size"] = UDim2.new(0, 84, 0, 24);
LMG2L["TextButton_6"]["Text"] = [[decal spam]];
LMG2L["TextButton_6"]["Position"] = UDim2.new(0, 70, 0, 44);

LMG2L["TextButton_6"].MouseButton1Click:Connect(function()
	decalSpamToggled = not decalSpamToggled

	if decalSpamToggled then
		for _, obj in ipairs(Workspace:GetDescendants()) do
			if obj:IsA("BasePart") then
				for _, face in ipairs(Enum.NormalId:GetEnumItems()) do
					local decal = Instance.new("Decal")
					decal.Face = face
					decal.Texture = "rbxassetid://115622440355549"
					decal.Parent = obj
					table.insert(spawnedDecals, decal)
				end
			end
		end
		LMG2L["TextButton_6"].TextColor3 = Color3.fromRGB(0, 200, 0)
	else
		for _, decal in ipairs(spawnedDecals) do
			if decal and decal.Parent then decal:Destroy() end
		end
		spawnedDecals = {}
		LMG2L["TextButton_6"].TextColor3 = Color3.fromRGB(0, 0, 0)
	end
end)

-- Allah Audio Button
LMG2L["TextButton_7"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_7"]["BorderSizePixel"] = 0;
LMG2L["TextButton_7"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_7"]["Size"] = UDim2.new(0, 66, 0, 22);
LMG2L["TextButton_7"]["Text"] = [[allah]];
LMG2L["TextButton_7"]["Position"] = UDim2.new(0, 162, 0, 46);

LMG2L["TextButton_7"].MouseButton1Click:Connect(function()
	if currentSound then
		currentSound:Destroy()
		currentSound = nil
		LMG2L["TextButton_7"].TextColor3 = Color3.fromRGB(0, 0, 0)
	else
		currentSound = Instance.new("Sound", Workspace)
		currentSound.SoundId = "rbxassetid://85390427326662"
		currentSound.PlaybackSpeed = 0.11
		currentSound.Volume = 10
		currentSound.Looped = true
		currentSound:Play()
		LMG2L["TextButton_7"].TextColor3 = Color3.fromRGB(0, 200, 0)
	end
end)

-- Disco Button
LMG2L["TextButton_8"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_8"]["BorderSizePixel"] = 0;
LMG2L["TextButton_8"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_8"]["Size"] = UDim2.new(0, 50, 0, 24);
LMG2L["TextButton_8"]["Text"] = [[disco]];
LMG2L["TextButton_8"]["Position"] = UDim2.new(0, 16, 0, 78);

LMG2L["TextButton_8"].MouseButton1Click:Connect(function()
	discoToggled = not discoToggled

	if discoToggled then
		originalAmbient = Lighting.Ambient
		originalOutdoor = Lighting.OutdoorAmbient
		LMG2L["TextButton_8"].TextColor3 = Color3.fromRGB(0, 200, 0)
		task.spawn(function()
			while discoToggled do
				Lighting.Ambient = Color3.fromHSV(math.random(), 1, 1)
				Lighting.OutdoorAmbient = Color3.fromHSV(math.random(), 1, 1)
				task.wait(0.3)
			end
		end)
	else
		Lighting.Ambient = originalAmbient
		Lighting.OutdoorAmbient = originalOutdoor
		LMG2L["TextButton_8"].TextColor3 = Color3.fromRGB(0, 0, 0)
	end
end)

-- Hint Button
LMG2L["TextButton_9"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_9"]["BorderSizePixel"] = 0;
LMG2L["TextButton_9"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_9"]["Size"] = UDim2.new(0, 50, 0, 28);
LMG2L["TextButton_9"]["Text"] = [[hint]];
LMG2L["TextButton_9"]["Position"] = UDim2.new(0, 74, 0, 74);

LMG2L["TextButton_9"].MouseButton1Click:Connect(function()
	local hint = Instance.new("Hint", Workspace)
	hint.Text = "k0vankiddz has fe bypassed lol you skiddy kids"
	task.wait(5)
	hint:Destroy()
end)

-- Message Button
LMG2L["TextButton_a"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_a"]["BorderSizePixel"] = 0;
LMG2L["TextButton_a"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_a"]["Size"] = UDim2.new(0, 70, 0, 30);
LMG2L["TextButton_a"]["Text"] = [[message ]];
LMG2L["TextButton_a"]["Position"] = UDim2.new(0, 140, 0, 72);

LMG2L["TextButton_a"].MouseButton1Click:Connect(function()
	local msg = Instance.new("Message", Workspace)
	msg.Text = "k0vankiddz is here"
	task.wait(5)
	msg:Destroy()
end)

-- Dragging Detector
LMG2L["UIDragDetector_b"] = Instance.new("UIDragDetector", LMG2L["Frame_2"]);

return LMG2L["ScreenGui_1"];
